mapper.select:
SELECT id, username, password, role, ref_id, status
FROM sys_user
WHERE username = #{username}

SELECT l.*, b.title book_title, b.isbn FROM inventory_log l JOIN book b ON b.id=l.book_id
b.title LIKE CONCAT('%',#{keyword},'%') OR b.isbn LIKE CONCAT('%',#{keyword},'%')
ORDER BY l.id DESC LIMIT #{offset},#{size}

mapper.update:
UPDATE borrow_reservation SET status='CANCELLED'
WHERE id=#{id} AND status IN('WAITING','READY')
AND reader_id=#{readerId}

mapper.select:
SELECT rv.*, r.name reader_name, r.student_no, b.title book_title, b.author FROM borrow_reservation rv
JOIN reader r ON r.id=rv.reader_id JOIN book b ON b.id=rv.book_id
 ORDER BY rv.id DESC LIMIT #{offset},#{size}
